// ============ shared UI ============
function SectionTitle({ jp, en }) {
  const lang = useLang();
  const primary = lang === "en" ? en : jp;
  const secondary = lang === "en" ? null : en; // EN時は日本語の副見出しを出さない
  return (
    <div style={{ marginBottom: 16 }}>
      <div className="gh-display" style={{ fontSize: 22, fontWeight: 700 }}>{primary}</div>
      {secondary && <div style={{ fontSize: 11, color: C.gold, letterSpacing: ".18em", textTransform: "uppercase", marginTop: 2 }}>{secondary}</div>}
    </div>
  );
}

function Card({ children, style }) {
  return <div style={{ background: C.surface, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, ...style }}>{children}</div>;
}

function Radar({ axes, current, target }) {
  const cx = 160, cy = 150, R = 110, N = axes.length;
  const pt = (i, v) => {
    const ang = (Math.PI * 2 * i) / N - Math.PI / 2;
    return [cx + Math.cos(ang) * R * (v / 5), cy + Math.sin(ang) * R * (v / 5)];
  };
  const poly = (vals) => vals.map((v, i) => pt(i, v).join(",")).join(" ");
  return (
    <svg viewBox="0 0 320 300" style={{ width: "100%", maxWidth: 380 }} role="img" aria-label="能力のレーダー">
      {[1, 2, 3, 4, 5].map((r) => (
        <polygon key={r} points={poly(axes.map(() => r))} fill="none" stroke={C.line} strokeWidth="1" />
      ))}
      {axes.map((a, i) => {
        const [x, y] = pt(i, 5.9);
        return <text key={a} x={x} y={y} fontSize="10" fill={C.muted} textAnchor="middle">{a}</text>;
      })}
      <polygon points={poly(target)} fill={C.teal + "22"} stroke={C.teal} strokeWidth="1.5" strokeDasharray="4 3" />
      <polygon points={poly(current)} fill={C.wine + "44"} stroke={C.wine} strokeWidth="2" />
    </svg>
  );
}

function ArchDiagram({ diagram, selected, onSelect, positions, onDrag, lang, controls }) {
  const svgRef = useRef(null);
  const drag = useRef(null);
  const pan = useRef(null);
  const [hover, setHover] = useState(null);
  const [focus, setFocus] = useState(false);   // 選んだノードに繋がるものだけを強調する
  const [order, setOrder] = useState(false);   // 入口から順に番号を振る（説明の順路）
  const [zoom, setZoom] = useState(1);
  const [shift, setShift] = useState({ x: 0, y: 0 });
  const en = lang === "en";
  const pos = positions || {};
  const nodeXY = (n) => pos[n.id] || { x: n.x, y: n.y };
  const map = {};
  diagram.nodes.forEach((n) => (map[n.id] = nodeXY(n)));
  const c = (id) => [map[id].x + NW / 2, map[id].y + NH / 2];
  const edges = diagram.edges.filter(([a, b]) => map[a] && map[b]);

  // 矢印は箱の縁で止める（中心まで伸ばすと矢尻が箱に隠れる）
  const edgePoint = (from, to) => {
    const [cx, cy] = c(from), [tx, ty] = c(to);
    const dx = tx - cx, dy = ty - cy;
    if (!dx && !dy) return [cx, cy];
    const k = Math.min(Math.abs(dx) ? NW / 2 / Math.abs(dx) : Infinity, Math.abs(dy) ? NH / 2 / Math.abs(dy) : Infinity);
    return [tx - dx * k, ty - dy * k];
  };

  // 入口（入ってくる矢印がないノード）から幅優先で「流れの順番」を振る
  const orderNo = useMemo(() => {
    const incoming = {}, out = {};
    diagram.nodes.forEach((n) => { incoming[n.id] = 0; out[n.id] = []; });
    edges.forEach(([a, b]) => { if (out[a]) out[a].push(b); if (incoming[b] !== undefined) incoming[b]++; });
    const queue = diagram.nodes.filter((n) => !incoming[n.id]).map((n) => n.id);
    const seen = new Set(queue);
    const no = {};
    let i = 0;
    while (queue.length) {
      const id = queue.shift();
      no[id] = ++i;
      (out[id] || []).forEach((nx) => { if (!seen.has(nx)) { seen.add(nx); queue.push(nx); } });
    }
    diagram.nodes.forEach((n) => { if (!no[n.id]) no[n.id] = ++i; }); // 閉路だけの島も拾う
    return no;
  }, [diagram, edges.length]);

  const active = hover || selected;                      // 強調の基準になるノード
  const linked = useMemo(() => {
    if (!active) return null;
    const s = new Set([active]);
    edges.forEach(([a, b]) => { if (a === active) s.add(b); if (b === active) s.add(a); });
    return s;
  }, [active, edges.length, diagram]);
  const dimmed = (id) => focus && linked && !linked.has(id);
  const edgeOn = (a, b) => active && (a === active || b === active);

  // クライアント座標 → SVGのviewBox座標へ変換
  const vb = diagram.view.split(" ").map(Number); // [minx,miny,w,h]
  const view = `${vb[0] + shift.x} ${vb[1] + shift.y} ${vb[2] / zoom} ${vb[3] / zoom}`;
  const toSvg = (clientX, clientY) => {
    const svg = svgRef.current;
    if (!svg) return { x: 0, y: 0 };
    const r = svg.getBoundingClientRect();
    const v = view.split(" ").map(Number);
    const sx = v[2] / r.width, sy = v[3] / r.height;
    return { x: v[0] + (clientX - r.left) * sx, y: v[1] + (clientY - r.top) * sy };
  };
  const start = (e, id) => {
    const p = e.touches ? e.touches[0] : e;
    const s = toSvg(p.clientX, p.clientY);
    const cur = map[id];
    drag.current = { id, dx: s.x - cur.x, dy: s.y - cur.y, moved: false };
  };
  const move = (e) => {
    const p = e.touches ? e.touches[0] : e;
    if (drag.current) {
      const s = toSvg(p.clientX, p.clientY);
      drag.current.moved = true;
      onDrag(drag.current.id, Math.round(s.x - drag.current.dx), Math.round(s.y - drag.current.dy));
      if (e.cancelable) e.preventDefault();
      return;
    }
    if (pan.current) { // 背景のドラッグは図全体を動かす（拡大時に端を見るため）
      const k = vb[2] / zoom / (svgRef.current ? svgRef.current.getBoundingClientRect().width : vb[2]);
      setShift({ x: pan.current.x0 - (p.clientX - pan.current.cx) * k, y: pan.current.y0 - (p.clientY - pan.current.cy) * k });
      if (e.cancelable) e.preventDefault();
    }
  };
  const end = (id) => {
    const wasDrag = drag.current && drag.current.moved;
    drag.current = null;
    if (!wasDrag) onSelect(id); // 動かさなければクリック扱い
  };
  const stopAll = () => { drag.current = null; pan.current = null; };
  const startPan = (e) => {
    if (zoom === 1) return;
    const p = e.touches ? e.touches[0] : e;
    pan.current = { cx: p.clientX, cy: p.clientY, x0: shift.x, y0: shift.y };
  };
  const resetView = () => { setZoom(1); setShift({ x: 0, y: 0 }); };
  const nodeName = (n) => (en ? (n.en || n.label) : n.label);
  const hoverNode = hover ? diagram.nodes.find((n) => n.id === hover) : null;
  const hoverRole = hoverNode && diagram.details && diagram.details[hover] ? diagram.details[hover].role : null;

  return (
    <div>
      {controls && (
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center", marginBottom: 8 }}>
          <button className="gh-btn" onClick={() => setFocus(!focus)} aria-pressed={focus}
                  style={{ fontSize: 11, padding: "3px 9px", ...(focus ? { borderColor: C.gold, color: C.gold, fontWeight: 700 } : {}) }}>
            {en ? "Focus on links" : "関連だけ強調"}
          </button>
          <button className="gh-btn" onClick={() => setOrder(!order)} aria-pressed={order}
                  style={{ fontSize: 11, padding: "3px 9px", ...(order ? { borderColor: C.gold, color: C.gold, fontWeight: 700 } : {}) }}>
            {en ? "Number the flow" : "流れに番号"}
          </button>
          <span style={{ flex: 1 }} />
          <button className="gh-btn" onClick={() => setZoom(Math.max(1, Math.round((zoom - 0.25) * 100) / 100))} disabled={zoom <= 1}
                  title={en ? "Zoom out" : "縮小"} style={{ fontSize: 11, padding: "3px 10px" }}>−</button>
          <span style={{ fontSize: 10.5, color: C.dim, minWidth: 34, textAlign: "center" }}>{Math.round(zoom * 100)}%</span>
          <button className="gh-btn" onClick={() => setZoom(Math.min(2.5, Math.round((zoom + 0.25) * 100) / 100))} disabled={zoom >= 2.5}
                  title={en ? "Zoom in" : "拡大"} style={{ fontSize: 11, padding: "3px 10px" }}>＋</button>
          {(zoom !== 1 || shift.x !== 0 || shift.y !== 0) && (
            <button className="gh-btn" onClick={resetView} style={{ fontSize: 11, padding: "3px 9px" }}>{en ? "Fit" : "全体に戻す"}</button>
          )}
        </div>
      )}
      <div className="gh-figscroll">
        <svg ref={svgRef} viewBox={view} style={{ width: "100%", touchAction: "none", cursor: zoom > 1 ? "grab" : "default" }}
             role="img" aria-label={diagram.title}
             onMouseDown={startPan} onMouseMove={move} onMouseUp={stopAll} onMouseLeave={() => { stopAll(); setHover(null); }}
             onTouchStart={startPan} onTouchMove={move} onTouchEnd={stopAll}>
          <defs>
            <marker id="ad-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
              <path d="M0,0 L10,5 L0,10 z" fill="#6E63A6" />
            </marker>
            <marker id="ad-arrow-on" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse">
              <path d="M0,0 L10,5 L0,10 z" fill={C.gold} />
            </marker>
          </defs>
          {edges.map(([a, b], i) => {
            const [x1, y1] = edgePoint(b, a); // a の縁から
            const [x2, y2] = edgePoint(a, b); // b の縁まで
            const on = edgeOn(a, b);
            return (
              <line key={i} x1={x1} y1={y1} x2={x2} y2={y2}
                    stroke={on ? C.gold : "#4A4070"} strokeWidth={on ? 2.2 : 1.5}
                    markerEnd={on ? "url(#ad-arrow-on)" : "url(#ad-arrow)"}
                    opacity={focus && active && !on ? 0.18 : 1} />
            );
          })}
          {diagram.nodes.map((n) => {
            const p = map[n.id];
            const isSel = selected === n.id;
            const isHov = hover === n.id;
            return (
              <g key={n.id} className="gh-node" style={{ cursor: "grab" }} opacity={dimmed(n.id) ? 0.28 : 1}
                 onMouseDown={(e) => { e.stopPropagation(); start(e, n.id); }} onMouseUp={() => end(n.id)}
                 onMouseEnter={() => setHover(n.id)} onMouseLeave={() => setHover(null)}
                 onTouchStart={(e) => { e.stopPropagation(); start(e, n.id); }}
                 tabIndex={0} role="button"
                 onFocus={() => setHover(n.id)} onBlur={() => setHover(null)}
                 onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSelect(n.id); } }}>
                <rect x={p.x} y={p.y} width={NW} height={NH} rx="9"
                      fill={isSel ? C.wineDeep : C.surface2}
                      stroke={isSel ? C.gold : (isHov ? C.teal : C.line)} strokeWidth={isSel ? 2 : (isHov ? 1.6 : 1)} />
                <text x={p.x + NW / 2} y={p.y + 19} fontSize="12" fill={C.text} textAnchor="middle" fontWeight="600" style={{ pointerEvents: "none" }}>{nodeName(n)}</text>
                <text x={p.x + NW / 2} y={p.y + 34} fontSize="9" fill={C.muted} textAnchor="middle" style={{ pointerEvents: "none" }}>{en ? n.label : n.en}</text>
                {order && (
                  <g style={{ pointerEvents: "none" }}>
                    <circle cx={p.x} cy={p.y} r="10" fill={C.bg} stroke={C.teal} strokeWidth="1.2" />
                    <text x={p.x} y={p.y + 3.5} fontSize="10" fill={C.teal} textAnchor="middle" fontWeight="700">{orderNo[n.id]}</text>
                  </g>
                )}
                <title>{nodeName(n)}</title>
              </g>
            );
          })}
        </svg>
      </div>
      <div style={{ fontSize: 10.5, color: C.dim, marginTop: 6, lineHeight: 1.6, minHeight: 28 }}>
        {hoverRole
          ? <span><span style={{ color: C.teal }}>{nodeName(hoverNode)}</span>：{hoverRole}</span>
          : (en ? "Arrows show which component calls which. Hover a node for its role, click for details. Use focus mode to keep only what it touches, number the flow for the order, and ＋ / drag to enlarge and move."
                : "矢印は「どこがどこを呼ぶか」の向きです。ノードに触れると役割、クリックで詳細が出ます。「関連だけ強調」で周辺だけに絞り、「流れに番号」で処理順が出ます。＋で拡大・ドラッグで移動できます。")}
      </div>
    </div>
  );
}

// 出典バッジ（実リンク）
function EvidenceLinks({ refs }) {
  if (!refs || refs.length === 0) return null;
  return (
    <div style={{ marginTop: 12, borderTop: `1px solid ${C.line}`, paddingTop: 10 }}>
      <div style={{ fontSize: 10.5, color: C.teal, letterSpacing: ".15em", marginBottom: 6 }}>出典・一次情報（クリックで開く）</div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
        {refs.map((rk) => {
          const src = SOURCES[rk];
          if (!src) return null;
          return (
            <a key={rk} href={src.u} target="_blank" rel="noopener noreferrer"
               style={{ fontSize: 11, color: C.gold, textDecoration: "none", border: `1px solid ${C.line}`, borderRadius: 6, padding: "4px 8px", display: "inline-flex", alignItems: "center", gap: 5 }}>
              <span style={{ fontSize: 9, color: C.teal, border: `1px solid ${C.teal}`, borderRadius: 4, padding: "1px 4px" }}>{src.k}</span>
              {src.t} ↗
            </a>
          );
        })}
      </div>
    </div>
  );
}

// ============ 業界別アーキテクチャパターン ============
// 「A → B → C」形式のスタック文字列を、番号つきチップの視覚的パイプラインに変換する。
function StackFlow({ steps, compact }) {
  const arr = Array.isArray(steps) ? steps : String(steps || "").split(/→|->|➡/).map((s) => s.trim()).filter(Boolean);
  if (!arr.length) return null;
  const fs = compact ? 10.5 : 11.5;
  const pad = compact ? "5px 9px" : "7px 11px";
  const bs = compact ? 16 : 19;
  return (
    <div className="gh-figscroll" style={{ display: "flex", alignItems: "center", flexWrap: "wrap", gap: compact ? 4 : 6, background: C.bg, border: `1px solid ${C.line}`, borderRadius: 8, padding: compact ? "8px 9px" : "12px 12px" }}>
      {arr.map((s, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: compact ? 4 : 6 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 7, background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 8, padding: pad }}>
            <span style={{ flexShrink: 0, width: bs, height: bs, borderRadius: "50%", background: C.gold, color: "#1a1204", fontSize: bs * 0.58, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center" }}>{i + 1}</span>
            <span style={{ fontSize: fs, fontWeight: 700, color: C.text, lineHeight: 1.35 }}>{s}</span>
          </div>
          {i < arr.length - 1 && <span style={{ color: C.gold, fontSize: compact ? 13 : 15, fontWeight: 700 }}>→</span>}
        </div>
      ))}
    </div>
  );
}

function IndustryView() {
  const lang = useLang();
  const [open, setOpen] = useState(null);
  const __opBack = useLocalHistory([[open, setOpen]]);
  useRegisterBack(__opBack.back, __opBack.canBack);
  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, marginBottom: 14, lineHeight: 1.7 }}>
        {t(lang, "iv_intro")}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(min(100%, 300px),1fr))", gap: 12 }}>
        {INDUSTRY_PATTERNS.map((p) => {
          const isOpen = open === p.ind;
          return (
            <Card key={p.ind} style={isOpen ? { borderColor: C.gold, gridColumn: "1 / -1" } : {}}>
              <div style={{ cursor: "pointer" }} onClick={() => setOpen(isOpen ? null : p.ind)}>
                <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                  <span style={{ fontSize: 20 }}>{p.icon}</span>
                  <span className="gh-display" style={{ fontSize: 16, color: C.gold }}>{lang === "en" ? (p.indEn || p.ind) : p.ind}</span>
                </div>
                <div style={{ fontSize: 13, fontWeight: 700, margin: "6px 0 6px" }}>{lang === "en" ? p.titleEn : p.title}</div>
                <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>{lang === "en" ? p.problemEn : p.problem}</div>
                {!isOpen && <div style={{ marginTop: 8 }}><StackFlow steps={lang === "en" ? p.stackEn : p.stack} compact /></div>}
                {!isOpen && <div style={{ fontSize: 10.5, color: C.teal, marginTop: 8, textAlign: "right" }}>{t(lang, "iv_detail")}</div>}
              </div>
              {isOpen && (
                <div style={{ marginTop: 12, display: "grid", gap: 12 }}>
                  <div>
                    <div style={{ fontSize: 10.5, color: C.teal, letterSpacing: ".15em", marginBottom: 6 }}>{lang === "en" ? "PIPELINE" : "処理パイプライン"}</div>
                    <StackFlow steps={lang === "en" ? p.stackEn : p.stack} />
                  </div>
                  <div>
                    <div style={{ fontSize: 10.5, color: C.teal, letterSpacing: ".15em", marginBottom: 4 }}>{t(lang, "iv_pattern")}</div>
                    <div style={{ fontSize: 12.5, lineHeight: 1.8 }}>{lang === "en" ? p.patternEn : p.pattern}</div>
                  </div>
                  <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(260px,1fr))", gap: 10 }}>
                    <div style={{ background: C.surface2, borderRadius: 8, padding: "9px 11px", borderLeft: `3px solid ${C.gold}` }}>
                      <span style={{ color: C.gold, fontWeight: 700, fontSize: 12 }}>◎ {t(lang, "iv_key")}</span>
                      <span style={{ fontSize: 12, lineHeight: 1.7 }}>{lang === "en" ? p.keyEn : p.key}</span>
                    </div>
                    <div style={{ background: C.surface2, borderRadius: 8, padding: "9px 11px", borderLeft: `3px solid ${C.wine}` }}>
                      <span style={{ color: C.wineInk, fontWeight: 700, fontSize: 12 }}>⚠ {t(lang, "iv_watch")}</span>
                      <span style={{ fontSize: 12, lineHeight: 1.7 }}>{lang === "en" ? p.watchEn : p.watch}</span>
                    </div>
                  </div>
                  <div style={{ fontSize: 11.5, color: C.muted, fontStyle: "italic" }}>
                    <span style={{ color: C.teal }}>{t(lang, "iv_exist")}</span>{lang === "en" ? p.existEn : p.exist}
                  </div>
                  <div style={{ borderTop: `1px solid ${C.line}`, paddingTop: 10 }}>
                    <div style={{ fontSize: 10.5, color: C.teal, letterSpacing: ".15em", marginBottom: 8 }}>{t(lang, "iv_related")}</div>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 16 }}>
                      {p.diagrams.filter((k) => DIAGRAMS[k]).map((k) => (
                        <div key={k}>
                          <div style={{ fontSize: 11.5, color: C.gold, fontWeight: 700, marginBottom: 4 }}>{diagramTitle(DIAGRAMS[k], lang)}</div>
                          <IndustryMiniDiagram diagram={DIAGRAMS[k]} lang={lang} />
                        </div>
                      ))}
                    </div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <button className="gh-btn" onClick={() => setOpen(null)} style={{ fontSize: 11 }}>{t(lang, "close")}</button>
                  </div>
                </div>
              )}
            </Card>
          );
        })}
      </div>
    </div>
  );
}

// 業界パターン内の縮小構成図（静的・非操作）
function IndustryMiniDiagram({ diagram }) {
  const lang = useLang();
  const en = lang === "en";
  const map = {};
  diagram.nodes.forEach((n) => (map[n.id] = n));
  const c = (id) => [map[id].x + NW / 2, map[id].y + NH / 2];
  return (
    <div className="gh-figscroll">
    <svg viewBox={diagram.view} style={{ width: "100%", background: C.bg, borderRadius: 8, border: `1px solid ${C.line}` }} role="img" aria-label={diagram.title}>
      {diagram.edges.map(([a, b], i) => {
        const [x1, y1] = c(a); const [x2, y2] = c(b);
        return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#4A4070" strokeWidth="1.5" />;
      })}
      {diagram.nodes.map((n) => (
        <g key={n.id}>
          <rect x={n.x} y={n.y} width={NW} height={NH} rx="9" fill={C.surface2} stroke={C.line} strokeWidth="1" />
          <text x={n.x + NW / 2} y={n.y + 19} fontSize="12" fill={C.text} textAnchor="middle" fontWeight="600">{en ? (n.en || n.label) : n.label}</text>
          <text x={n.x + NW / 2} y={n.y + 34} fontSize="9" fill={C.muted} textAnchor="middle">{en ? n.label : n.en}</text>
        </g>
      ))}
    </svg>
    </div>
  );
}

// ============ インタラクティブ・アーキテクチャクイズ ============
function ArchQuizView() {
  const lang = useLang();
  const MODES = [["node", "aq_node"], ["choice", "aq_choice"], ["fill", "aq_fill"], ["anti", "aq_anti"], ["order", "aq_order"]];
  const [mode, setMode] = useState("node");
  const [idx, setIdx] = useState(0);
  const [picked, setPicked] = useState(null); // ユーザーの選択（node型はnodeId, 他はindex/文字列）
  const __opBack = useLocalHistory([[mode, setMode], [idx, setIdx], [picked, setPicked]]);
  useRegisterBack(__opBack.back, __opBack.canBack);
  const [answered, setAnswered] = useState(false);
  const [done, setDone] = useState(false); // このモードを最後まで解いたら完了画面を出す
  const [score, setScore] = useState({ node: 0, choice: 0, fill: 0, anti: 0, order: 0 });
  const [seen, setSeen] = useState({ node: 0, choice: 0, fill: 0, anti: 0, order: 0 });
  const slot = useQuizSlot("gafa_archquiz_resume_v1");
  // オンデマンド翻訳: "mode:idx" -> 翻訳済みオブジェクト。永続キャッシュ。
  const [trans, setTrans] = useState({});
  const [transBusy, setTransBusy] = useState(false);
  const [transErr, setTransErr] = useState("");
  const [showOrig, setShowOrig] = useState(false);
  const AQ_TRANS_KEY = "gafa_archquiz_trans_v1";
  useEffect(() => {
    (async () => { try { const r = await window.storage.get(AQ_TRANS_KEY); if (r && r.value) setTrans(JSON.parse(r.value)); } catch (e) {} })();
  }, []);
  // 形式別に翻訳すべきフィールドを抽出→翻訳→structuralフィールドは温存
  const translateItem = async (m, i, item, manual) => {
    const key = m + ":" + i;
    if (trans[key]) return;
    setTransBusy(true); setTransErr("");
    try {
      let sys, usr;
      if (m === "node") {
        sys = "Translate Japanese AI-architecture quiz text to English. Output STRICT JSON only (no markdown), keys: ask (string), exp (string).";
        usr = "ask: " + item.ask + "\nexp: " + item.exp;
      } else if (m === "choice" || m === "order") {
        sys = "Translate Japanese AI-architecture quiz to English. Output STRICT JSON only, keys: q (string), opts (array of 4 strings, same order), exp (string). Keep exactly 4 options.";
        usr = "q: " + item.q + "\nopts: " + JSON.stringify(item.opts) + "\nexp: " + item.exp;
      } else if (m === "fill") {
        sys = "Translate Japanese AI-architecture quiz to English. Output STRICT JSON only, keys: title (string), desc (string), chain (array of strings, same length, keep the literal token \"[?]\" unchanged where present), a (string), opts (array of strings, same order), exp (string). 'a' must exactly match the translated option that equals the original answer.";
        usr = "title: " + item.title + "\ndesc: " + item.desc + "\nchain: " + JSON.stringify(item.chain) + "\na: " + item.a + "\nopts: " + JSON.stringify(item.opts) + "\nexp: " + item.exp;
      } else { // anti
        sys = "Translate Japanese AI-architecture quiz to English. Output STRICT JSON only, keys: scene (string), bad (string), why (string), fix (string).";
        usr = "scene: " + item.scene + "\nbad: " + item.bad + "\nwhy: " + item.why + "\nfix: " + item.fix;
      }
      const raw = await callClaude(sys, [{ role: "user", content: usr }], { quiet: !manual });
      const parsed = extractJSON(raw);
      // 最低限の形状チェック
      if (m === "node" && (!parsed.ask || !parsed.exp)) throw new Error("bad");
      if ((m === "choice" || m === "order") && (!Array.isArray(parsed.opts) || parsed.opts.length !== 4)) throw new Error("bad");
      if (m === "fill") {
        if (!Array.isArray(parsed.opts) || !Array.isArray(parsed.chain)) throw new Error("bad");
        // a が opts に無い場合は、元の正解位置に対応する翻訳optを採用してフォールバック
        if (!parsed.opts.includes(parsed.a)) {
          const origIdx = item.opts.indexOf(item.a);
          if (origIdx >= 0 && parsed.opts[origIdx]) parsed.a = parsed.opts[origIdx];
          else throw new Error("bad");
        }
      }
      if (m === "anti" && (!parsed.scene || !parsed.fix)) throw new Error("bad");
      const next = { ...trans, [key]: parsed };
      setTrans(next);
      try { await window.storage.set(AQ_TRANS_KEY, JSON.stringify(next)); } catch (e) {}
    } catch (e) {
      setTransErr(t(lang, "qz_transerr"));
    } finally { setTransBusy(false); }
  };

  const list = ARCH_QUIZ[mode];
  const q = list[idx];
  const modeLabel = t(lang, MODES.find(([m]) => m === mode)[1]);
  // 静的英語フィールドがあればそれをtrans形式に組み立てる（API翻訳不要で即時表示）
  const staticEn = (m, it) => {
    if (m === "node") return it.askEn && it.expEn ? { ask: it.askEn, exp: it.expEn } : null;
    if (m === "choice" || m === "order") return it.qEn && Array.isArray(it.optsEn) && it.expEn ? { q: it.qEn, opts: it.optsEn, exp: it.expEn } : null;
    if (m === "fill") return it.titleEn && it.descEn && Array.isArray(it.chainEn) && it.aEn && Array.isArray(it.optsEn) && it.expEn
      ? { title: it.titleEn, desc: it.descEn, chain: it.chainEn, a: it.aEn, opts: it.optsEn, exp: it.expEn } : null;
    if (m === "anti") return it.sceneEn && it.fixEn ? { scene: it.sceneEn, bad: it.badEn, why: it.whyEn, fix: it.fixEn } : null;
    return null;
  };
  // EN表示かつ未翻訳なら自動翻訳（フックは最上位で）。静的英語があればそれを最優先。
  const useEn = lang === "en" && !showOrig;
  const transKey = mode + ":" + idx;
  const sEn = useEn ? staticEn(mode, q) : null;
  const tq = sEn || (useEn ? trans[transKey] : null); // 静的英語→APIキャッシュの順で表示に使う
  useEffect(() => {
    if (useEn && !sEn && !trans[transKey] && !transBusy) translateItem(mode, idx, list[idx]);
  }, [transKey, useEn]);

  const switchMode = (m) => { setMode(m); setIdx(0); setPicked(null); setAnswered(false); setDone(false); };
  const choose = (val, correct) => {
    if (answered) return;
    setPicked(val); setAnswered(true);
    setSeen((s) => ({ ...s, [mode]: s[mode] + 1 }));
    if (correct) setScore((s) => ({ ...s, [mode]: s[mode] + 1 }));
  };
  const next = () => {
    if (idx + 1 >= list.length) { setDone(true); return; } // 最後まで来たら終了（無限ループしない）
    setPicked(null); setAnswered(false);
    setIdx((i) => i + 1);
  };
  const prevQ = () => { if (idx > 0) { setPicked(null); setAnswered(false); setIdx((i) => i - 1); } };
  const restart = () => { setIdx(0); setPicked(null); setAnswered(false); setDone(false); setScore((s) => ({ ...s, [mode]: 0 })); setSeen((s) => ({ ...s, [mode]: 0 })); };

  // 選択肢をシャッフル（決定的）: choice/fill用
  const shuffled = (arr, salt) => {
    const a = arr.map((v, i) => [v, i]);
    for (let i = a.length - 1; i > 0; i--) {
      const j = (salt * 9301 + i * 49297) % 233280 % (i + 1);
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a.map(([v]) => v);
  };

  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, marginBottom: 12, lineHeight: 1.7 }}>
        {t(lang, "aq_intro")}
      </div>
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        {MODES.map(([m, k]) => (
          <button key={m} className="gh-btn" onClick={() => switchMode(m)}
                  style={mode === m ? { borderColor: C.gold, color: C.gold, fontWeight: 700 } : {}}>{t(lang, k)}</button>
        ))}
        <span style={{ flex: 1 }} />
        <span style={{ fontSize: 12, color: C.teal }}>{t(lang, "aq_score")} {score[mode]} / {seen[mode]}</span>
        <button className="gh-btn" style={{ fontSize: 11, padding: "3px 9px", borderColor: C.teal, color: C.teal }}
          onClick={() => slot.save({ mode, idx, picked, answered, done, score, seen }, modeLabel)}>{slot.meta ? (lang === "en" ? "💾 Saved" : "💾 保存済") : (lang === "en" ? "💾 Save" : "💾 セーブ")}</button>
        {slot.meta && (
          <button className="gh-btn" style={{ fontSize: 11, padding: "3px 9px" }}
            onClick={async () => { const d = await slot.read(); if (!d) return; setMode(d.mode || "node"); setIdx(d.idx || 0); setPicked(d.picked == null ? null : d.picked); setAnswered(!!d.answered); setDone(!!d.done); setScore(d.score || score); setSeen(d.seen || seen); }}>{lang === "en" ? "▶ Resume" : "▶ 続きから"}</button>
        )}
      </div>
      {lang === "en" && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10, fontSize: 11 }}>
          {transBusy && !tq && <span style={{ color: C.teal }}>{t(lang, "qz_translating")}</span>}
          {transErr && !tq && <span style={{ color: C.wineInk }}>{transErr} <button className="gh-btn" style={{ fontSize: 10, padding: "2px 8px" }} onClick={() => translateItem(mode, idx, list[idx], true)}>↻</button></span>}
          {tq && <button className="gh-btn" style={{ fontSize: 10, padding: "2px 10px" }} onClick={() => setShowOrig((v) => !v)}>{showOrig ? t(lang, "qz_translate") : t(lang, "qz_showoriginal")}</button>}
        </div>
      )}

      {done && (
        <Card>
          <div style={{ fontSize: 11, color: C.wineInk, letterSpacing: ".2em", marginBottom: 6 }}>{modeLabel}</div>
          <div className="gh-display" style={{ fontSize: 18, marginBottom: 8 }}>{lang === "en" ? "Mode complete" : "このモードを一周しました"}</div>
          <div style={{ fontSize: 14, color: C.teal, marginBottom: 14 }}>{t(lang, "aq_score")} {score[mode]} / {seen[mode]}（{seen[mode] ? Math.round(score[mode] / seen[mode] * 100) : 0}%）</div>
          <button className="gh-btn gh-btn-primary" onClick={restart}>{lang === "en" ? "Restart this mode" : "このモードをもう一度"}</button>
          <div style={{ fontSize: 11.5, color: C.muted, marginTop: 10 }}>{lang === "en" ? "Pick another mode from the tabs above." : "他のモードは上のタブから選べます。"}</div>
        </Card>
      )}

      {/* ノード当て */}
      {!done && mode === "node" && (
        <Card>
          <div style={{ fontSize: 11, color: C.wineInk, letterSpacing: ".2em", marginBottom: 6 }}>{modeLabel}（{idx + 1}/{list.length}）</div>
          <div className="gh-display" style={{ fontSize: 17, marginBottom: 4 }}>{tq ? tq.ask : q.ask}</div>
          <div style={{ fontSize: 11.5, color: C.muted, marginBottom: 10 }}>{t(lang, "aq_clicknode")}</div>
          <ArchQuizDiagram diagram={DIAGRAMS[q.fig]} answered={answered} picked={picked} answer={q.answer}
                           lang={lang} onPick={(id) => choose(id, id === q.answer)} />
          {answered && (
            <div style={{ marginTop: 10, fontSize: 12.5, lineHeight: 1.8, background: C.bg, border: `1px solid ${picked === q.answer ? C.teal : C.wine}`, borderRadius: 8, padding: "10px 12px" }}>
              <span style={{ color: picked === q.answer ? C.teal : C.wine, fontWeight: 700 }}>{picked === q.answer ? t(lang, "correct") : t(lang, "wrong")}</span>
              {picked !== q.answer && <span style={{ color: C.muted }}>（{t(lang, "aq_answeris")}「{nodeLabel(DIAGRAMS[q.fig].nodes.find((n) => n.id === q.answer), lang)}」）</span>}
              <br />{tq ? tq.exp : q.exp}
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12 }}>
            <button className="gh-btn" onClick={prevQ} disabled={idx === 0} style={{ padding: "9px 22px", opacity: idx === 0 ? 0.45 : 1 }}>{lang === "en" ? "← Prev" : "← 前へ"}</button>
            <button className="gh-btn gh-btn-primary" onClick={next} disabled={!answered} style={{ padding: "9px 22px", opacity: answered ? 1 : 0.45 }}>{idx + 1 >= list.length ? (lang === "en" ? "See results" : "結果を見る") : t(lang, "next_q")}</button>
          </div>
        </Card>
      )}

      {/* 四択 */}
      {!done && (mode === "choice" || mode === "order") && (
        <Card>
          <div style={{ fontSize: 11, color: C.wineInk, letterSpacing: ".2em", marginBottom: 6 }}>{modeLabel}{lang === "en" ? " (" + (idx + 1) + "/" + list.length + ")" : "（" + (idx + 1) + "/" + list.length + "）"}</div>
          <div className="gh-display" style={{ fontSize: 17, marginBottom: 12 }}>{tq ? tq.q : q.q}</div>
          <div style={{ display: "grid", gap: 8 }}>
            {q.opts.map((o, i) => {
              const isCorrect = i === q.a, isPicked = picked === i;
              const bg = answered ? (isCorrect ? C.wineDeep : (isPicked ? "#3a2030" : C.surface2)) : C.surface2;
              const bd = answered ? (isCorrect ? C.teal : (isPicked ? C.wine : C.line)) : C.line;
              return (
                <button key={i} onClick={() => choose(i, isCorrect)} disabled={answered}
                        style={{ textAlign: "left", background: bg, border: `1px solid ${bd}`, borderRadius: 8, padding: "10px 12px", color: C.text, fontSize: 13, cursor: answered ? "default" : "pointer", lineHeight: 1.6 }}>
                  {answered && isCorrect && <span style={{ color: C.teal, fontWeight: 700 }}>✓ </span>}
                  {answered && isPicked && !isCorrect && <span style={{ color: C.wineInk, fontWeight: 700 }}>✗ </span>}
                  {tq ? tq.opts[i] : o}
                </button>
              );
            })}
          </div>
          {answered && (
            <div style={{ marginTop: 10, fontSize: 12.5, lineHeight: 1.8, background: C.bg, border: `1px solid ${C.gold}`, borderRadius: 8, padding: "10px 12px" }}>
              <span style={{ color: C.gold, fontWeight: 700 }}>{t(lang, "aq_expl")}</span>{tq ? tq.exp : q.exp}
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12 }}>
            <button className="gh-btn" onClick={prevQ} disabled={idx === 0} style={{ padding: "9px 22px", opacity: idx === 0 ? 0.45 : 1 }}>{lang === "en" ? "← Prev" : "← 前へ"}</button>
            <button className="gh-btn gh-btn-primary" onClick={next} disabled={!answered} style={{ padding: "9px 22px", opacity: answered ? 1 : 0.45 }}>{idx + 1 >= list.length ? (lang === "en" ? "See results" : "結果を見る") : t(lang, "next_q")}</button>
          </div>
        </Card>
      )}

      {/* 空欄埋め */}
      {!done && mode === "fill" && (
        <Card>
          <div style={{ fontSize: 11, color: C.wineInk, letterSpacing: ".2em", marginBottom: 6 }}>{modeLabel}（{idx + 1}/{list.length}）</div>
          <div className="gh-display" style={{ fontSize: 16, marginBottom: 4 }}>{tq ? tq.title : q.title}</div>
          <div style={{ fontSize: 12, color: C.muted, marginBottom: 12 }}>{tq ? tq.desc : q.desc}</div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center", marginBottom: 14 }}>
            {(tq ? tq.chain : q.chain).map((step, i) => (
              <React.Fragment key={i}>
                <span style={{ fontSize: 12, padding: "8px 12px", borderRadius: 8, background: step === "[?]" ? (answered ? C.wineDeep : "#2a2440") : C.surface2, border: `1px solid ${step === "[?]" ? C.gold : C.line}`, color: step === "[?]" ? C.gold : C.text, fontWeight: step === "[?]" ? 700 : 400 }}>
                  {step === "[?]" ? (answered ? (tq ? tq.a : q.a) : "？") : step}
                </span>
                {i < (tq ? tq.chain : q.chain).length - 1 && <span style={{ color: C.dim }}>→</span>}
              </React.Fragment>
            ))}
          </div>
          <div style={{ fontSize: 11.5, color: C.muted, marginBottom: 8 }}>{t(lang, "aq_fillprompt")}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(140px,1fr))", gap: 8 }}>
            {shuffled((tq ? tq.opts : q.opts), idx + 1).map((o) => {
              const ansStr = tq ? tq.a : q.a;
              const isCorrect = o === ansStr, isPicked = picked === o;
              const bg = answered ? (isCorrect ? C.wineDeep : (isPicked ? "#3a2030" : C.surface2)) : C.surface2;
              const bd = answered ? (isCorrect ? C.teal : (isPicked ? C.wine : C.line)) : C.line;
              return (
                <button key={o} onClick={() => choose(o, isCorrect)} disabled={answered}
                        style={{ background: bg, border: `1px solid ${bd}`, borderRadius: 8, padding: "10px 12px", color: C.text, fontSize: 12.5, cursor: answered ? "default" : "pointer" }}>
                  {answered && isCorrect && <span style={{ color: C.teal, fontWeight: 700 }}>✓ </span>}
                  {o}
                </button>
              );
            })}
          </div>
          {answered && (
            <div style={{ marginTop: 10, fontSize: 12.5, lineHeight: 1.8, background: C.bg, border: `1px solid ${C.gold}`, borderRadius: 8, padding: "10px 12px" }}>
              <span style={{ color: C.gold, fontWeight: 700 }}>{t(lang, "aq_expl")}</span>{tq ? tq.exp : q.exp}
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12 }}>
            <button className="gh-btn" onClick={prevQ} disabled={idx === 0} style={{ padding: "9px 22px", opacity: idx === 0 ? 0.45 : 1 }}>{lang === "en" ? "← Prev" : "← 前へ"}</button>
            <button className="gh-btn gh-btn-primary" onClick={next} disabled={!answered} style={{ padding: "9px 22px", opacity: answered ? 1 : 0.45 }}>{idx + 1 >= list.length ? (lang === "en" ? "See results" : "結果を見る") : t(lang, "next_q")}</button>
          </div>
        </Card>
      )}

      {/* アンチパターン */}
      {!done && mode === "anti" && (
        <Card>
          <div style={{ fontSize: 11, color: C.wineInk, letterSpacing: ".2em", marginBottom: 6 }}>{modeLabel}（{idx + 1}/{list.length}）</div>
          <div style={{ fontSize: 13.5, lineHeight: 1.8, background: C.surface2, borderRadius: 8, padding: "12px 14px", marginBottom: 12, borderLeft: `3px solid ${C.wine}` }}>
            {tq ? tq.scene : q.scene}
          </div>
          <div style={{ fontSize: 12, color: C.muted, marginBottom: 10 }}>{t(lang, "aq_antiq")}</div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <button className="gh-btn" onClick={() => choose("ok", false)} disabled={answered}
                    style={answered && picked === "ok" ? { borderColor: C.wine, color: C.wineInk } : {}}>{t(lang, "aq_sound")}</button>
            <button className="gh-btn" onClick={() => choose("bad", true)} disabled={answered}
                    style={answered && picked === "bad" ? { borderColor: C.teal, color: C.teal } : {}}>{t(lang, "aq_hasproblem")}</button>
          </div>
          {answered && (
            <div style={{ marginTop: 12, fontSize: 12.5, lineHeight: 1.8 }}>
              <div style={{ color: picked === "bad" ? C.teal : C.wine, fontWeight: 700, marginBottom: 6 }}>
                {(picked === "bad" ? t(lang, "correct") : t(lang, "wrong")) + " — " + t(lang, "aq_isanti")}
              </div>
              <div style={{ background: C.bg, borderRadius: 8, padding: "10px 12px", border: `1px solid ${C.line}` }}>
                <div style={{ marginBottom: 6 }}><span style={{ color: C.wineInk, fontWeight: 700 }}>{t(lang, "aq_problem")}（{tq ? tq.bad : q.bad}）：</span>{tq ? tq.why : q.why}</div>
                <div><span style={{ color: C.teal, fontWeight: 700 }}>{t(lang, "aq_fix")}</span>{tq ? tq.fix : q.fix}</div>
              </div>
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12 }}>
            <button className="gh-btn" onClick={prevQ} disabled={idx === 0} style={{ padding: "9px 22px", opacity: idx === 0 ? 0.45 : 1 }}>{lang === "en" ? "← Prev" : "← 前へ"}</button>
            <button className="gh-btn gh-btn-primary" onClick={next} disabled={!answered} style={{ padding: "9px 22px", opacity: answered ? 1 : 0.45 }}>{idx + 1 >= list.length ? (lang === "en" ? "See results" : "結果を見る") : t(lang, "next_q")}</button>
          </div>
        </Card>
      )}
    </div>
  );
}

// ノード当てクイズ用の図面（クリックで解答、正誤で色付け・ドラッグ不可）
function ArchQuizDiagram({ diagram, answered, picked, answer, onPick, lang }) {
  const en = lang === "en";
  const map = {};
  diagram.nodes.forEach((n) => (map[n.id] = n));
  const c = (id) => [map[id].x + NW / 2, map[id].y + NH / 2];
  const fillOf = (id) => {
    if (!answered) return C.surface2;
    if (id === answer) return C.wineDeep;      // 正解ノード
    if (id === picked) return "#3a2030";        // 誤答で選んだノード
    return C.surface2;
  };
  const strokeOf = (id) => {
    if (!answered) return C.line;
    if (id === answer) return C.teal;
    if (id === picked) return C.wine;
    return C.line;
  };
  return (
    <div className="gh-figscroll">
    <svg viewBox={diagram.view} style={{ width: "100%" }} role="img" aria-label={diagram.title}>
      {diagram.edges.map(([a, b], i) => {
        const [x1, y1] = c(a); const [x2, y2] = c(b);
        return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#4A4070" strokeWidth="1.5" />;
      })}
      {diagram.nodes.map((n) => (
        <g key={n.id} className="gh-node" style={{ cursor: answered ? "default" : "pointer" }}
           onClick={() => !answered && onPick(n.id)} tabIndex={0} role="button"
           onKeyDown={(e) => { if (e.key === "Enter" && !answered) onPick(n.id); }}>
          <rect x={n.x} y={n.y} width={NW} height={NH} rx="9"
                fill={fillOf(n.id)} stroke={strokeOf(n.id)} strokeWidth={answered && (n.id === answer || n.id === picked) ? 2 : 1} />
          <text x={n.x + NW / 2} y={n.y + 19} fontSize="12" fill={C.text} textAnchor="middle" fontWeight="600" style={{ pointerEvents: "none" }}>{en ? (n.en || n.label) : n.label}</text>
          <text x={n.x + NW / 2} y={n.y + 34} fontSize="9" fill={C.muted} textAnchor="middle" style={{ pointerEvents: "none" }}>{en ? n.label : n.en}</text>
        </g>
      ))}
    </svg>
    </div>
  );
}

// ============ Tab components ============
// 学習ホーム: SRS解答履歴から定着度・弱点・今日の復習を集約（読み取り専用）
function LearningHome() {
  const lang = useLang();
  const { setJump } = useJump();
  const [srs, setSrs] = useState(null);
  useEffect(() => {
    (async () => {
      try { const r = await window.storage.get("gafa_srs_v1"); setSrs(r && r.value ? JSON.parse(r.value) : {}); }
      catch (e) { setSrs({}); }
    })();
  }, []);
  if (srs === null) return null; // ロード中は描画しない
  const now = Date.now();
  const qis = Object.keys(srs).map(Number).filter((qi) => qi < MCQS.length);
  const tracked = qis.length;
  if (tracked === 0) {
    return (
      <Card style={{ borderColor: C.line, marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
          <span className="gh-display" style={{ fontSize: 16, color: C.gold }}>{t(lang, "lh_title")}</span>
        </div>
        <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7 }}>{t(lang, "lh_empty")}</div>
      </Card>
    );
  }
  const due = qis.filter((qi) => srs[qi].due <= now);
  const mastered = qis.filter((qi) => (srs[qi].interval || 0) >= 21);
  // テーマ別集計: reps>0を「定着寄与」、due<=nowを「要復習」としてカウント
  const byTheme = {};
  qis.forEach((qi) => {
    const cat = MCQS[qi].cat;
    if (!byTheme[cat]) byTheme[cat] = { total: 0, dueCnt: 0, masteredCnt: 0, intervalSum: 0 };
    const th = byTheme[cat];
    th.total += 1;
    if (srs[qi].due <= now) th.dueCnt += 1;
    if ((srs[qi].interval || 0) >= 21) th.masteredCnt += 1;
    th.intervalSum += (srs[qi].interval || 0);
  });
  const themeRows = Object.keys(byTheme).map((cat) => {
    const th = byTheme[cat];
    const retention = Math.round((th.masteredCnt / th.total) * 100); // 定着率(=間隔21日以上の割合)
    return { cat, ...th, retention };
  });
  // 定着度順（高い順）
  const byRetention = [...themeRows].sort((a, b) => b.retention - a.retention);
  // 弱点順(要復習が多い順→定着率が低い順)
  const byWeak = [...themeRows].sort((a, b) => (b.dueCnt - a.dueCnt) || (a.retention - b.retention)).filter((r) => r.dueCnt > 0 || r.retention < 100);
  const catLabel = (c) => (lang === "en" ? (CAT_EN[c] || c) : (CAT_JA[c] || c));
  const startReview = () => setJump({ tab: "dojo", dojoView: "mcq", srsReview: true });
  const bar = (pct, color) => (
    <div style={{ flex: 1, height: 6, background: C.bg, borderRadius: 3, overflow: "hidden" }}>
      <div style={{ width: pct + "%", height: "100%", background: color }} />
    </div>
  );
  return (
    <Card style={{ borderColor: C.gold, marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
        <span className="gh-display" style={{ fontSize: 16, color: C.gold }}>{t(lang, "lh_title")}</span>
      </div>
      <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.7, marginBottom: 12 }}>{t(lang, "lh_sub")}</div>
      {/* サマリ3指標 */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%, 150px),1fr))", gap: 10, marginBottom: 14 }}>
        <div style={{ background: C.surface2, borderRadius: 8, padding: "10px 12px", border: `1px solid ${due.length > 0 ? C.gold : C.line}` }}>
          <div style={{ fontSize: 10.5, color: C.muted }}>{t(lang, "lh_due")}</div>
          <div style={{ fontSize: 22, fontWeight: 700, color: due.length > 0 ? C.gold : C.text }}>{due.length}<span style={{ fontSize: 12, color: C.muted }}>{t(lang, "lh_qcount")}</span></div>
        </div>
        <div style={{ background: C.surface2, borderRadius: 8, padding: "10px 12px", border: `1px solid ${C.line}` }}>
          <div style={{ fontSize: 10.5, color: C.muted }}>{t(lang, "lh_tracked")}</div>
          <div style={{ fontSize: 22, fontWeight: 700, color: C.text }}>{tracked}<span style={{ fontSize: 12, color: C.muted }}>{t(lang, "lh_qcount")}</span></div>
        </div>
        <div style={{ background: C.surface2, borderRadius: 8, padding: "10px 12px", border: `1px solid ${C.line}` }}>
          <div style={{ fontSize: 10.5, color: C.muted }}>{t(lang, "lh_mastered")}</div>
          <div style={{ fontSize: 22, fontWeight: 700, color: C.teal }}>{mastered.length}<span style={{ fontSize: 12, color: C.muted }}>{t(lang, "lh_qcount")}</span></div>
        </div>
      </div>
      {due.length > 0 && (
        <button className="gh-btn gh-btn-primary" onClick={startReview} style={{ marginBottom: 14 }}>
          {t(lang, "lh_start")}（{due.length}）
        </button>
      )}
      {/* 弱点テーマ */}
      {byWeak.length > 0 && (
        <div style={{ marginBottom: 12 }}>
          <div style={{ fontSize: 11, color: C.wineInk, letterSpacing: ".1em", marginBottom: 8 }}>{t(lang, "lh_weak")}</div>
          <div style={{ display: "grid", gap: 6 }}>
            {byWeak.slice(0, 5).map((r) => (
              <div key={r.cat} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 11.5 }}>
                <span style={{ width: 96, color: C.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{catLabel(r.cat)}</span>
                {bar(r.retention, C.wine)}
                <span style={{ width: 74, textAlign: "right", color: C.muted, fontSize: 10.5, whiteSpace: "nowrap" }}>{r.dueCnt > 0 ? (r.dueCnt + (lang === "en" ? " due" : "問要復習")) : (r.retention + "%")}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      {/* テーマ別定着度 */}
      <div>
        <div style={{ fontSize: 11, color: C.teal, letterSpacing: ".1em", marginBottom: 8 }}>{t(lang, "lh_bytheme")} <span style={{ color: C.dim, fontSize: 9.5 }}>{t(lang, "lh_masteredhint")}</span></div>
        <div style={{ display: "grid", gap: 6 }}>
          {byRetention.map((r) => (
            <div key={r.cat} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 11.5 }}>
              <span style={{ width: 96, color: C.muted, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{catLabel(r.cat)}</span>
              {bar(r.retention, C.teal)}
              <span style={{ width: 74, textAlign: "right", color: C.gold, fontSize: 10.5 }}>{r.masteredCnt}/{r.total}</span>
            </div>
          ))}
        </div>
      </div>
    </Card>
  );
}

// ---------- TechHub 全体の学習記録（各道場の正答率・弱い領域・復習待ちを1枚に。読むだけ） ----------
const THR_CHECK = [
  { key: "govdojo_stats_v1", name: ["セキュリティ・ガバナンス道場（判定演習）", "Security & Governance Dojo (drills)"], bank: () => GOVDOJO_BANK, dom: () => GOVDOJO_DOMAINS, open: { hash: "#megatech/govdojo/quiz" } },
  { key: "itsec_stats_v1", name: ["ITセキュリティ基盤", "IT Security Foundations"], bank: () => ITSEC_BANK, dom: () => ITSEC_DOMAINS, open: { tab: "itsec" } },
  { key: "noteissue_stats_v1", name: ["実務論点マップ", "Practice Issue Map"], bank: () => NOTEISSUE_BANK, dom: () => NOTEISSUE_DOMAINS, open: { tab: "noteissues" } },
  { key: "slalom_stats_v1", name: ["Slalom変革道場", "Slalom Transformation Dojo"], bank: () => SLALOM_BANK, dom: () => SLALOM_DOMAINS, open: { tab: "slalom" } },
  { key: "axcheck_core_stats_v1", name: ["理解度チェック 基礎", "Check — Core"], bank: () => CHECK_CORE_BANK, dom: () => CHECK_DOMAINS_CORE, open: { tab: "checkcore" } },
  { key: "axcheck_ax_stats_v1", name: ["理解度チェック AX実務", "Check — AX"], bank: () => CHECK_AX_BANK, dom: () => CHECK_DOMAINS_AX, open: { tab: "checkax" } },
];
function TechHubRecords() {
  const lang = useLang();
  const en = lang === "en";
  const L = (x) => (Array.isArray(x) ? x[en ? 1 : 0] : x || "");
  const { setJump } = useJump();
  const [rows, setRows] = useState(null);
  useEffect(() => {
    let live = true;
    (async () => {
      const get = async (k) => { try { const r = await window.storage.get(k); return r && r.value ? JSON.parse(r.value) : null; } catch (e) { return null; } };
      const out = [];
      // 技術道場：間隔反復の記録（問題ごと）
      const srs = (await get("gafa_srs_v1")) || {};
      const qis = Object.keys(srs).map(Number).filter((q) => q < MCQS.length);
      const now = Date.now();
      out.push({ id: "dojo", name: ["技術道場（クイズ）", "Tech Dojo (quiz)"], size: MCQS.length, seen: qis.length, ans: null, acc: null, weak: null, review: qis.filter((q) => srs[q] && srs[q].due <= now).length, reviewL: ["復習の期限", "due for review"], open: { jump: qis.some((q) => srs[q] && srs[q].due <= now) ? { tab: "dojo", dojoView: "mcq", srsReview: true } : { tab: "dojo", dojoView: "mcq" } } });
      // AIアーキテクト道場：問題ごとの正誤
      const ac = (await get("acad_quiz_score_v1")) || {};
      const ks = Object.keys(ac).filter((k) => ACAD_QUIZ[k]);
      const byT = {};
      ks.forEach((k) => { const tp = ACAD_QUIZ[k].topic || "-"; byT[tp] = byT[tp] || { c: 0, a: 0 }; byT[tp].a++; if (ac[k] === true) byT[tp].c++; });
      const wt = Object.entries(byT).filter(([, v]) => v.a >= 3).sort((p, q) => p[1].c / p[1].a - q[1].c / q[1].a)[0];
      const okN = ks.filter((k) => ac[k] === true).length;
      out.push({ id: "architect", name: ["AIアーキテクト道場", "AI Architect Dojo"], size: ACAD_QUIZ.length, seen: ks.length, ans: ks.length, acc: ks.length ? Math.round((okN / ks.length) * 100) : null, weak: wt ? `${wt[0]}（${Math.round((wt[1].c / wt[1].a) * 100)}%）` : null, review: ks.filter((k) => ac[k] === false).length, reviewL: ["不正解のまま", "still wrong"], open: { tab: "architect" } });
      // 判定演習の各エンジン：テーマごとの正答数と、復習キュー
      for (const c of THR_CHECK) {
        const st = (await get(c.key)) || {};
        const wr = (await get(c.key.replace("_stats_", "_wrong_"))) || {};
        const doms = c.dom();
        let a = 0, ok = 0; Object.values(st).forEach((v) => { a += v.a || 0; ok += v.c || 0; });
        const w = doms.map((d) => ({ d, v: st[d.id] })).filter((x) => x.v && x.v.a >= 3).sort((p, q) => p.v.c / p.v.a - q.v.c / q.v.a)[0];
        out.push({ id: c.key, name: c.name, size: c.bank().length, seen: null, ans: a, acc: a ? Math.round((ok / a) * 100) : null, weak: w ? `${en ? w.d.en : w.d.ja}（${Math.round((w.v.c / w.v.a) * 100)}%）` : null, review: Object.keys(wr).length, reviewL: ["復習キュー", "in review queue"], open: c.open });
      }
      // ケース演習（書く）：メモを書いたケース数と、ルーブリックの自己採点の平均
      const cn = (await get("axcase_notes_v1")) || {};
      const cr = (await get("axcase_rubric_v1")) || {};
      const wrote = Object.keys(cn).filter((k) => cn[k] && Object.values(cn[k]).some((x) => String(x || "").trim())).length;
      const scored = Object.keys(cr).filter((k) => cr[k] && Object.keys(cr[k]).length);
      const avg = scored.length ? scored.reduce((p, k) => p + Object.keys(cr[k]).length, 0) / scored.length : null;
      const cp = (await get("axcase_pro_v1")) || {};
      const proN = Object.keys(cp).filter((k) => cp[k] && Object.keys(cp[k]).length);
      const proAvg = proN.length ? proN.reduce((p, k) => p + Object.keys(cp[k]).length, 0) / proN.length : null;
      const cwNote = [avg != null ? (en ? `rubric avg ${avg.toFixed(1)} (${scored.length} scored)` : `自己採点 平均${avg.toFixed(1)}項目（${scored.length}件）`) : null, proAvg != null ? (en ? `top-tier check avg ${proAvg.toFixed(1)}/10` : `超一流の点検 平均${proAvg.toFixed(1)}/10`) : null].filter(Boolean).join(en ? "; " : "・");
      out.push({ id: "casework", name: ["ケース演習（書く）", "Case Work (written)"], size: CASE_CARDS.length, seen: wrote, unit: ["件に記入", " written"], ans: null, acc: null, weak: null, note: cwNote || null, review: 0, reviewL: ["", ""], open: { tab: "casework" } });
      if (live) setRows(out);
    })();
    return () => { live = false; };
  }, []);
  if (!rows) return null;
  const active = rows.filter((r) => (r.ans || 0) + (r.seen || 0) > 0);
  const totA = rows.reduce((p, r) => p + (r.ans || 0), 0);
  const totRev = rows.reduce((p, r) => p + (r.review || 0), 0);
  const go = (o) => { if (o.hash) { try { window.location.hash = o.hash; } catch (e) {} } else if (o.jump) setJump(o.jump); else setJump({ tab: o.tab }); try { window.scrollTo({ top: 0, behavior: "smooth" }); } catch (e) {} };
  const sorted = rows.slice().sort((p, q) => ((q.ans || 0) + (q.seen || 0) > 0) - ((p.ans || 0) + (p.seen || 0) > 0) || (q.review || 0) - (p.review || 0));
  const accCol = (a) => (a == null ? C.dim : a >= 80 ? C.teal : a >= 60 ? C.gold : C.wineInk);
  return (
    <Card style={{ borderColor: C.line, marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, flexWrap: "wrap", marginBottom: 4 }}>
        <span className="gh-display" style={{ fontSize: 16, color: C.gold }}>{en ? "Records across TechHub" : "道場ごとの記録（TechHub全体）"}</span>
        <span style={{ fontSize: 11.5, color: C.muted }}>{en ? `${active.length} of ${rows.length} dojos started · ${totA} answers · ${totRev} to review` : `${rows.length}道場中 ${active.length}つに記録・解答 ${totA}回・復習待ち ${totRev}問`}</span>
      </div>
      <div style={{ fontSize: 11, color: C.dim, marginBottom: 10 }}>{en ? "Read from what each dojo saves on this device. Answers count every attempt; the weakest area needs at least 3 answers." : "各道場がこの端末に保存している記録を読んで並べた。解答は回答した回数。弱い領域は3回以上答えた領域から出す。"}</div>
      <div className="gh-figscroll">
        <div style={{ minWidth: 620, display: "grid", gridTemplateColumns: "minmax(170px,1.6fr) 70px 70px minmax(90px,1fr) minmax(130px,1.3fr) 92px 64px", gap: "4px 8px", alignItems: "center", fontSize: 11.5 }}>
          {(en ? ["Dojo", "Questions", "Answers", "Accuracy", "Weakest area", "To review", ""] : ["道場", "問題数", "解答", "正答率", "弱い領域", "復習待ち", ""]).map((h, i) => <div key={i} style={{ fontSize: 10.5, color: C.dim, fontWeight: 700, borderBottom: `1px solid ${C.line}`, paddingBottom: 3 }}>{h}</div>)}
          {sorted.map((r) => {
            const has = (r.ans || 0) + (r.seen || 0) > 0;
            return (
              <React.Fragment key={r.id}>
                <div style={{ color: has ? C.text : C.muted, fontWeight: 700 }}>{L(r.name)}</div>
                <div style={{ color: C.muted, fontVariantNumeric: "tabular-nums" }}>{r.size}</div>
                <div style={{ color: C.text, fontVariantNumeric: "tabular-nums" }}>{r.ans != null ? r.ans : `${r.seen}${r.unit ? L(r.unit) : (en ? " seen" : "問")}`}</div>
                <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                  {r.acc != null ? <><div style={{ flex: 1, height: 6, background: C.surface2, borderRadius: 3, overflow: "hidden" }}><div style={{ width: r.acc + "%", height: "100%", background: accCol(r.acc) }} /></div><span style={{ color: C.text, fontVariantNumeric: "tabular-nums", width: 34, textAlign: "right" }}>{r.acc}%</span></> : <span style={{ color: C.dim }}>—</span>}
                </div>
                <div style={{ color: r.weak ? C.wineInk : r.note ? C.muted : C.dim }}>{r.weak || r.note || "—"}</div>
                <div style={{ color: r.review ? C.gold : C.dim, fontVariantNumeric: "tabular-nums" }}>{r.review ? `${r.review}` : "0"}<span style={{ fontSize: 10, color: C.dim }}> {L(r.reviewL)}</span></div>
                <button className="gh-btn" onClick={() => go(r.open)} style={{ fontSize: 11, padding: "3px 9px" }}>{has ? (en ? "Open" : "開く") : (en ? "Start" : "始める")}</button>
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </Card>
  );
}

// 立ち位置（ポジショニング）を一文にするカード。入力はこの端末に保存する
const POSITIONING_KEY = "techhub_positioning_v1";
const POSITIONING_FIELDS = [
  { k: "who", l: ["誰の（業界 × 規模 × AIの成熟度）", "For whom (industry × size × AI maturity)"], ph: ["例：従業員1,000人前後の製造業で、PoCは経験したが本番に進めていない会社", "e.g. manufacturers of about 1,000 people that have run a PoC but not reached production"] },
  { k: "pain", l: ["どんな課題", "Which problem"], ph: ["例：効果を損益で説明できず、次の予算が通らない", "e.g. cannot explain the benefit in P&L terms, so the next budget does not pass"] },
  { k: "alt", l: ["比べられる相手（代わりの選択肢）", "Compared with (the alternatives)"], ph: ["例：大手SIerの一括請負、ツール販売、内製", "e.g. a large integrator's fixed-price build, a tool vendor, building in-house"] },
  { k: "value", l: ["自分だけの価値（武器の組み合わせ）", "What only you offer (your assets combined)"], ph: ["例：導入と定着まで持った経験 × ベンダーに寄らない方式の比較", "e.g. having owned adoption end to end × vendor-neutral comparison of approaches"] },
  { k: "not", l: ["やらない領域（3つ）", "What you will not take on (three)"], ph: ["例：ツールの再販／判定基準を決めないPoC／…", "e.g. reselling tools / a PoC without decision criteria / …"] },
];
function PositioningCard() {
  const en = useLang() === "en";
  const [v, setV] = useState({});
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    let live = true;
    (async () => {
      try { const r = await window.storage.get(POSITIONING_KEY); if (live && r && r.value) setV(JSON.parse(r.value) || {}); } catch (e) { /* 初回は記録が無い */ }
      if (live) setLoaded(true);
    })();
    return () => { live = false; };
  }, []);
  const set = (k, val) => {
    const d = new Date();
    const next = { ...v, [k]: val, at: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}` };
    setV(next);
    try { window.storage.set(POSITIONING_KEY, JSON.stringify(next)); } catch (e) { /* 保存できない環境では画面の間だけ */ }
  };
  if (!loaded) return null;
  const f = (k) => (v[k] || "").trim();
  const ready = f("who") && f("pain") && f("value");
  const sentence = en
    ? `For ${f("who") || "…"}, facing ${f("pain") || "…"}, I provide ${f("value") || "…"}${f("alt") ? `, unlike ${f("alt")}` : ""}.`
    : `${f("who") || "…"}の「${f("pain") || "…"}」に対して、${f("alt") ? f("alt") + "と違い、" : ""}${f("value") || "…"}を提供する。`;
  const box = { width: "100%", boxSizing: "border-box", background: C.surface2, color: C.text, border: `1px solid ${C.line}`, borderRadius: 8, padding: "7px 10px", fontSize: 12.5, fontFamily: "inherit", lineHeight: 1.6, resize: "vertical" };
  return (
    <Card style={{ marginBottom: 8 }}>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.75, marginBottom: 10 }}>
        {en ? "A top-tier consultant is recalled in one sentence: whose problem you are the person for. Fill the blanks, read the sentence aloud in 30 seconds, and revisit it every quarter. What you type is saved on this device."
          : "超一流のコンサルタントは「誰のどんな課題なら、この人」と一文で思い出される。欄を埋めて、下の一文を30秒で声に出し、四半期ごとに見直す。入力はこの端末に保存される。"}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%, 280px),1fr))", gap: 10 }}>
        {POSITIONING_FIELDS.map((x) => (
          <label key={x.k} style={{ display: "block", fontSize: 11.5, color: C.gold, fontWeight: 700 }}>
            {x.l[en ? 1 : 0]}
            <textarea rows={2} value={v[x.k] || ""} onChange={(e) => set(x.k, e.target.value)} placeholder={x.ph[en ? 1 : 0]} style={{ ...box, marginTop: 4 }} />
          </label>
        ))}
      </div>
      <div style={{ marginTop: 12, background: C.surface2, borderLeft: `3px solid ${ready ? C.teal : C.line}`, borderRadius: 6, padding: "9px 12px" }}>
        <div style={{ fontSize: 10.5, color: C.dim, fontWeight: 700, letterSpacing: ".08em", marginBottom: 3 }}>{en ? "YOUR ONE SENTENCE" : "あなたの一文"}</div>
        <div style={{ fontSize: 13.5, color: ready ? C.text : C.muted, lineHeight: 1.75 }}>{sentence}</div>
        {f("not") ? <div style={{ fontSize: 12, color: C.muted, marginTop: 6, lineHeight: 1.7 }}>{en ? "Will not take on: " : "やらない領域："}{f("not")}</div> : null}
        {v.at ? <div style={{ fontSize: 10.5, color: C.dim, marginTop: 6 }}>{en ? `Last edited ${v.at}` : `最終更新 ${v.at}`}</div> : null}
      </div>
    </Card>
  );
}

// 能力ごとの「できること」と、鍛える場所（押すとそのタブへ移る）
function CompetencyMap() {
  const lang = useLang();
  const en = lang === "en";
  const { setJump } = useJump();
  const L = (x) => x[en ? 1 : 0];
  const dCol = { core: C.teal, ref: C.muted, opt: C.dim };
  const go = (tab) => { if (tab === "strategy") { const el = document.getElementById("th-positioning"); if (el && el.scrollIntoView) el.scrollIntoView({ behavior: "smooth", block: "start" }); return; } setJump({ tab }); try { window.scrollTo({ top: 0, behavior: "smooth" }); } catch (e) { /* 何もしない */ } };
  return (
    <div>
      <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.75, marginBottom: 10 }}>
        {en ? "Nine abilities, each with what it looks like and where to train it. \"Train here\" tabs are the core; \"look up\" tabs are dictionaries you do not need to read through; \"optional\" tabs can be skipped."
          : "9つの能力ごとに、できる姿と鍛える場所を並べた。「ここで鍛える」が核、「必要なとき引く」は辞書として使い通読しなくてよい、「任意」は飛ばしてよい。"}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%, 330px),1fr))", gap: 10 }}>
        {COMP.map((c, i) => (
          <Card key={c.id} style={{ padding: 13 }}>
            <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
              <span className="gh-display" style={{ color: C.gold, fontSize: 17 }}>{i + 1}</span>
              <span style={{ fontSize: 13.5, fontWeight: 800 }}>{L(c.name)}</span>
            </div>
            <div style={{ fontSize: 12, color: C.text, lineHeight: 1.7, margin: "6px 0 8px" }}>{L(c.can)}</div>
            {["core", "ref", "opt"].map((d) => {
              const ps = c.places.filter((p) => p.d === d);
              if (!ps.length) return null;
              return (
                <div key={d} style={{ marginBottom: 6 }}>
                  <div style={{ fontSize: 10.5, fontWeight: 700, color: dCol[d], letterSpacing: ".04em", marginBottom: 3 }}>{L(COMP_DEPTH[d])}</div>
                  <div style={{ display: "flex", flexWrap: "wrap", gap: 5 }}>
                    {ps.map((p) => (
                      <button key={p.tab + p.m} type="button" className="gh-btn" onClick={() => go(p.tab)} title={L(p.n)}
                        style={{ fontSize: 11.5, padding: "4px 9px", borderRadius: 8, border: `1px solid ${d === "core" ? C.teal : C.line}`, background: "transparent", color: d === "core" ? C.text : C.muted, cursor: "pointer", textAlign: "left", lineHeight: 1.5 }}>
                        <b style={{ fontWeight: 700 }}>{p.tab === "strategy" ? (en ? "This page" : "このページ") : t(lang, "tab_" + p.tab)}</b>
                        <span style={{ color: C.dim }}> · {L(COMP_MODE[p.m])} · {L(p.n)}</span>
                      </button>
                    ))}
                  </div>
                </div>
              );
            })}
            {c.gap ? <div style={{ fontSize: 11.5, color: C.wineInk, lineHeight: 1.65, marginTop: 6 }}>△ {L(c.gap)}</div> : null}
          </Card>
        ))}
      </div>
    </div>
  );
}

